-- A57: batch b002_de, chunk 3 (25 videos for learners of de). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (6820,4222,7845,7563,5053,8000,98,5272,4424,4408,5636,8028,637,7739,7813,7997,7748,7450,7040,5517,4125,347,7849,4920,4434)) then
    raise exception 'A57 out/b002_de_03.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (6820,4222,7845,7563,5053,8000,98,5272,4424,4408,5636,8028,637,7739,7813,7997,7748,7450,7040,5517,4125,347,7849,4920,4434)) <> 25 then
    raise exception 'A57 out/b002_de_03.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
